/**
 * 表示用于包含流体的方块（如炼药锅）中的流体类型。
 */
export enum FluidType {
    /**
     * @remarks
     * 代表熔岩作为一种流体类型。
     *
     */
    Lava = 'Lava',
    /**
     * @remarks
     * 代表药水作为一种流体类型。
     *
     */
    Potion = 'Potion',
    /**
     * @remarks
     * 代表细雪作为一种流体类型。
     *
     */
    PowderSnow = 'PowderSnow',
    /**
     * @remarks
     * 代表水作为一种流体类型。
     *
     */
    Water = 'Water',
}